23	public final class AppStoreUtils {
24	
25	    private static final String TAG = "AppStoreUtils";
26	
27	    private static final String GOOGLE_PLAY_APP_STORE_PACKAGE_NAME = "com.android.vending";
28	
29	    /**
30	     * 获取跳转到应用商店的 Intent
31	     *
32	     * @return 跳转到应用商店的 Intent
33	     */
34	    public static Intent getAppStoreIntent() {
35	        return getAppStoreIntent(Utils.getApp().getPackageName(), false);
36	    }
37	
38	    /**
39	     * 获取跳转到应用商店的 Intent
40	     *
41	     * @param isIncludeGooglePlayStore 是否包括 Google Play 商店
42	     * @return 跳转到应用商店的 Intent
43	     */
44	    public static Intent getAppStoreIntent(boolean isIncludeGooglePlayStore) {
45	        return getAppStoreIntent(Utils.getApp().getPackageName(), isIncludeGooglePlayStore);
46	    }
47	
48	    /**
49	     * 获取跳转到应用商店的 Intent
50	     *
51	     * @param packageName 包名
52	     * @return 跳转到应用商店的 Intent
53	     */
54	    public static Intent getAppStoreIntent(final String packageName) {
55	        return getAppStoreIntent(packageName, false);
56	    }
57	
58	    /**
59	     * 获取跳转到应用商店的 Intent
60	     * <p>优先跳转到手机自带的应用市场</p>
61	     *
62	     * @param packageName              包名
63	     * @param isIncludeGooglePlayStore 是否包括 Google Play 商店
64	     * @return 跳转到应用商店的 Intent
65	     */
66	    public static Intent getAppStoreIntent(final String packageName, boolean isIncludeGooglePlayStore) {
67	        if (RomUtils.isSamsung()) {// 三星单独处理跳转三星市场
68	            Intent samsungAppStoreIntent = getSamsungAppStoreIntent(packageName);
69	            if (samsungAppStoreIntent != null) return samsungAppStoreIntent;
70	        }
71	        if (RomUtils.isLeeco()) {// 乐视单独处理跳转乐视市场
72	            Intent leecoAppStoreIntent = getLeecoAppStoreIntent(packageName);
73	            if (leecoAppStoreIntent != null) return leecoAppStoreIntent;
74	        }
75	
76	        Uri uri = Uri.parse("market://details?id=" + packageName);
77	        Intent intent = new Intent();
78	        intent.setData(uri);
79	        intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
80	        List<ResolveInfo> resolveInfos = Utils.getApp().getPackageManager()
81	                .queryIntentActivities(intent, PackageManager.MATCH_DEFAULT_ONLY);
82	        if (resolveInfos == null || resolveInfos.size() == 0) {
83	            Log.e(TAG, "No app store!");
84	            return null;
85	        }
86	        Intent googleIntent = null;
87	        for (ResolveInfo resolveInfo : resolveInfos) {
88	            String pkgName = resolveInfo.activityInfo.packageName;
89	            if (!GOOGLE_PLAY_APP_STORE_PACKAGE_NAME.equals(pkgName)) {
90	                if (AppUtils.isAppSystem(pkgName)) {
91	                    intent.setPackage(pkgName);
92	                    return intent;
93	                }
94	            } else {
95	                intent.setPackage(GOOGLE_PLAY_APP_STORE_PACKAGE_NAME);
96	                googleIntent = intent;
97	            }
98	        }
99	        if (isIncludeGooglePlayStore && googleIntent != null) {
100	            return googleIntent;
101	        }
102	
103	        intent.setPackage(resolveInfos.get(0).activityInfo.packageName);
104	        return intent;
105	    }
106	
107	    private static Intent getSamsungAppStoreIntent(final String packageName) {
108	        Intent intent = new Intent();
109	        intent.setClassName("com.sec.android.app.samsungapps", "com.sec.android.app.samsungapps.Main");
110	        intent.setData(Uri.parse("http://www.samsungapps.com/appquery/appDetail.as?appId=" + packageName));
111	        intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
112	        if (getAvailableIntentSize(intent) > 0) {
113	            return intent;
114	        }
115	        return null;
116	    }
117	
118	    private static Intent getLeecoAppStoreIntent(final String packageName) {
119	        Intent intent = new Intent();
120	        intent.setClassName("com.letv.app.appstore", "com.letv.app.appstore.appmodule.details.DetailsActivity");
121	        intent.setAction("com.letv.app.appstore.appdetailactivity");
122	        intent.putExtra("packageName", packageName);
123	        intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);
124	        if (getAvailableIntentSize(intent) > 0) {
125	            return intent;
126	        }
127	        return null;
128	    }
129	
130	    private static int getAvailableIntentSize(final Intent intent) {
131	        return Utils.getApp().getPackageManager()
132	                .queryIntentActivities(intent, PackageManager.MATCH_DEFAULT_ONLY)
133	                .size();
134	    }
135	}
