30	public final class BatteryUtils {
31	
32	    @IntDef({BatteryStatus.UNKNOWN, BatteryStatus.DISCHARGING, BatteryStatus.CHARGING,
33	            BatteryStatus.NOT_CHARGING, BatteryStatus.FULL})
34	    @Retention(RetentionPolicy.SOURCE)
35	    public @interface BatteryStatus {
36	        int UNKNOWN      = BatteryManager.BATTERY_STATUS_UNKNOWN;
37	        int DISCHARGING  = BatteryManager.BATTERY_STATUS_DISCHARGING;
38	        int CHARGING     = BatteryManager.BATTERY_STATUS_CHARGING;
39	        int NOT_CHARGING = BatteryManager.BATTERY_STATUS_NOT_CHARGING;
40	        int FULL         = BatteryManager.BATTERY_STATUS_FULL;
41	    }
42	
43	    /**
44	     * Return whether the app is on the device's power whitelist.
45	     *
46	     * @return {@code true}: yes<br>{@code false}: no
47	     */
48	    @RequiresApi(api = Build.VERSION_CODES.M)
49	    public static boolean isIgnoringBatteryOptimizations() {
50	        return isIgnoringBatteryOptimizations(Utils.getApp().getPackageName());
51	    }
52	
53	    /**
54	     * Return whether the app is on the device's power whitelist.
55	     *
56	     * @return {@code true}: yes<br>{@code false}: no
57	     */
58	    @RequiresApi(api = Build.VERSION_CODES.M)
59	    public static boolean isIgnoringBatteryOptimizations(String pkgName) {
60	        try {
61	            PowerManager pm = (PowerManager) Utils.getApp().getSystemService(Context.POWER_SERVICE);
62	            //noinspection ConstantConditions
63	            return pm.isIgnoringBatteryOptimizations(pkgName);
64	        } catch (Exception e) {
65	            return true;
66	        }
67	    }
68	
69	    /**
70	     * Register the status of battery changed listener.
71	     *
72	     * @param listener The status of battery changed listener.
73	     */
74	    public static void registerBatteryStatusChangedListener(final OnBatteryStatusChangedListener listener) {
75	        BatteryChangedReceiver.getInstance().registerListener(listener);
76	    }
77	
78	    /**
79	     * Return whether the status of battery changed listener has been registered.
80	     *
81	     * @param listener The status of battery changed listener.
82	     * @return true to registered, false otherwise.
83	     */
84	    public static boolean isRegistered(final OnBatteryStatusChangedListener listener) {
85	        return BatteryChangedReceiver.getInstance().isRegistered(listener);
86	    }
87	
88	    /**
89	     * Unregister the status of battery changed listener.
90	     *
91	     * @param listener The status of battery changed listener.
92	     */
93	    public static void unregisterBatteryStatusChangedListener(final OnBatteryStatusChangedListener listener) {
94	        BatteryChangedReceiver.getInstance().unregisterListener(listener);
95	    }
96	
97	    public static final class BatteryChangedReceiver extends BroadcastReceiver {
98	
99	        private static BatteryChangedReceiver getInstance() {
100	            return BatteryChangedReceiver.LazyHolder.INSTANCE;
101	        }
102	
103	        private Set<OnBatteryStatusChangedListener> mListeners = new HashSet<>();
104	
105	        void registerListener(final OnBatteryStatusChangedListener listener) {
106	            if (listener == null) return;
107	            ThreadUtils.runOnUiThread(new Runnable() {
108	                @Override
109	                public void run() {
110	                    int preSize = mListeners.size();
111	                    mListeners.add(listener);
112	                    if (preSize == 0 && mListeners.size() == 1) {
113	                        IntentFilter intentFilter = new IntentFilter();
114	                        intentFilter.addAction(Intent.ACTION_BATTERY_CHANGED);
115	                        Utils.getApp().registerReceiver(BatteryChangedReceiver.getInstance(), intentFilter);
116	                    }
117	                }
118	            });
119	        }
120	
121	        boolean isRegistered(final OnBatteryStatusChangedListener listener) {
122	            if (listener == null) return false;
123	            return mListeners.contains(listener);
124	        }
125	
126	        void unregisterListener(final OnBatteryStatusChangedListener listener) {
127	            if (listener == null) return;
128	            ThreadUtils.runOnUiThread(new Runnable() {
129	                @Override
130	                public void run() {
131	                    int preSize = mListeners.size();
132	                    mListeners.remove(listener);
133	                    if (preSize == 1 && mListeners.size() == 0) {
134	                        Utils.getApp().unregisterReceiver(BatteryChangedReceiver.getInstance());
135	                    }
136	                }
137	            });
138	        }
139	
140	        @Override
141	        public void onReceive(Context context, final Intent intent) {
142	            if (Intent.ACTION_BATTERY_CHANGED.equals(intent.getAction())) {
143	                ThreadUtils.runOnUiThread(new Runnable() {
144	                    @Override
145	                    public void run() {
146	                        int level = intent.getIntExtra(BatteryManager.EXTRA_LEVEL, -1);
147	                        int status = intent.getIntExtra(BatteryManager.EXTRA_STATUS, BatteryStatus.UNKNOWN);
148	                        for (OnBatteryStatusChangedListener listener : mListeners) {
149	                            listener.onBatteryStatusChanged(new Status(level, status));
150	                        }
151	                    }
152	                });
153	            }
154	        }
155	
156	        private static class LazyHolder {
157	            private static final BatteryChangedReceiver INSTANCE = new BatteryChangedReceiver();
158	        }
159	    }
160	
161	    public interface OnBatteryStatusChangedListener {
162	        void onBatteryStatusChanged(Status status);
163	    }
164	
165	    public static final class Status {
166	        private int level;
167	        @BatteryStatus
168	        private int status;
169	
170	        Status(int level, int status) {
171	            this.level = level;
172	            this.status = status;
173	        }
174	
175	        public int getLevel() {
176	            return level;
177	        }
178	
179	        public void setLevel(int level) {
180	            this.level = level;
181	        }
182	
183	        @BatteryStatus
184	        public int getStatus() {
185	            return status;
186	        }
187	
188	        public void setStatus(int status) {
189	            this.status = status;
190	        }
191	
192	        @Override
193	        public String toString() {
194	            return batteryStatus2String(status) + ": " + level + "%";
195	        }
196	
197	        public static String batteryStatus2String(@BatteryStatus int status) {
198	            if (status == BatteryStatus.DISCHARGING) {
199	                return "discharging";
200	            }
201	            if (status == BatteryStatus.CHARGING) {
202	                return "charging";
203	            }
204	            if (status == BatteryStatus.NOT_CHARGING) {
205	                return "not_charging";
206	            }
207	            if (status == BatteryStatus.FULL) {
208	                return "full";
209	            }
210	            return "unknown";
211	        }
212	    }
213	}
