5	/**
6	 * <pre>
7	 *     author: Blankj
8	 *     blog  : http://blankj.com
9	 *     time  : 2018/03/21
10	 *     desc  : 位运算工具类
11	 * </pre>
12	 */
13	public final class BitUtils {
14	
15	    private BitUtils() {
16	        throw new UnsupportedOperationException("u can't instantiate me...");
17	    }
18	
19	    /**
20	     * 获取运算数指定位置的值<br>
21	     * 例如： 0000 1011 获取其第 0 位的值为 1, 第 2 位 的值为 0<br>
22	     *
23	     * @param source 需要运算的数
24	     * @param pos    指定位置 (0...7)
25	     * @return 指定位置的值(0 or 1)
26	     */
27	    public static byte getBitValue(byte source, int pos) {
28	        return (byte) ((source >> pos) & 1);
29	
30	    }
31	
32	
33	    /**
34	     * 将运算数指定位置的值置为指定值<br>
35	     * 例: 0000 1011 需要更新为 0000 1111, 即第 2 位的值需要置为 1<br>
36	     *
37	     * @param source 需要运算的数
38	     * @param pos    指定位置 (0<=pos<=7)
39	     * @param value  只能取值为 0, 或 1, 所有大于0的值作为1处理, 所有小于0的值作为0处理
40	     * @return 运算后的结果数
41	     */
42	    public static byte setBitValue(byte source, int pos, byte value) {
43	
44	        byte mask = (byte) (1 << pos);
45	        if (value > 0) {
46	            source |= mask;
47	
48	        } else {
49	            source &= (~mask);
50	
51	        }
52	        return source;
53	    }
54	
55	
56	    /**
57	     * 将运算数指定位置取反值<br>
58	     * 例： 0000 1011 指定第 3 位取反, 结果为 0000 0011; 指定第2位取反, 结果为 0000 1111<br>
59	     *
60	     * @param source
61	     * @param pos    指定位置 (0<=pos<=7)
62	     * @return 运算后的结果数
63	     */
64	    public static byte reverseBitValue(byte source, int pos) {
65	        byte mask = (byte) (1 << pos);
66	        return (byte) (source ^ mask);
67	
68	    }
69	
70	
71	    /**
72	     * 检查运算数的指定位置是否为1<br>
73	     *
74	     * @param source 需要运算的数
75	     * @param pos    指定位置 (0<=pos<=7)
76	     * @return true 表示指定位置值为1, false 表示指定位置值为 0
77	     */
78	    public static boolean checkBitValue(byte source, int pos) {
79	
80	        source = (byte) (source >>> pos);
81	
82	        return (source & 1) == 1;
83	
84	    }
85	
86	    /**
87	     * 入口函数做测试<br>
88	     *
89	     * @param args
90	     */
91	    public static void main(String[] args) {
92	        // 取十进制 11 (二级制 0000 1011) 为例子
93	        byte source = 11;
94	        // 取第2位值并输出, 结果应为 0000 1011
95	        for (byte i = 7; i >= 0; i--) {
96	            Log.d("BitUtils", getBitValue(source, i) + "");
97	
98	        }
99	        // 将第6位置为1并输出 , 结果为 75 (0100 1011)
100	        Log.d("BitUtils", setBitValue(source, 6, (byte) 1) + "");
101	
102	        // 将第6位取反并输出, 结果应为75(0100 1011)
103	        Log.d("BitUtils", reverseBitValue(source, 6) + "");
104	
105	        // 检查第6位是否为1，结果应为false
106	        Log.d("BitUtils", checkBitValue(source, 6) + "");
107	
108	        // 输出为1的位, 结果应为 0 1 3
109	        for (byte i = 0; i < 8; i++) {
110	            if (checkBitValue(source, i)) {
111	                Log.d("BitUtils", i + "");
112	            }
113	        }
114	    }
115	}
