3	import static java.lang.Math.PI;
4	
5	/**
6	 * <pre>
7	 *     author: Blankj
8	 *     blog  : http://blankj.com
9	 *     time  : 2018/03/21
10	 *     desc  : 坐标相关工具类
11	 * </pre>
12	 */
13	public final class CoordinateUtils {
14	
15	    private final static double X_PI = 3.14159265358979324 * 3000.0 / 180.0;
16	    private final static double A    = 6378245.0;
17	    private final static double EE   = 0.00669342162296594323;
18	
19	    /**
20	     * BD09 坐标转 GCJ02 坐标
21	     *
22	     * @param lng BD09 坐标纬度
23	     * @param lat BD09 坐标经度
24	     * @return GCJ02 坐标：[经度，纬度]
25	     */
26	    public static double[] bd09ToGcj02(double lng, double lat) {
27	        double x = lng - 0.0065;
28	        double y = lat - 0.006;
29	        double z = Math.sqrt(x * x + y * y) - 0.00002 * Math.sin(y * X_PI);
30	        double theta = Math.atan2(y, x) - 0.000003 * Math.cos(x * X_PI);
31	        double gg_lng = z * Math.cos(theta);
32	        double gg_lat = z * Math.sin(theta);
33	        return new double[]{gg_lng, gg_lat};
34	    }
35	
36	    /**
37	     * GCJ02 坐标转 BD09 坐标
38	     *
39	     * @param lng GCJ02 坐标经度
40	     * @param lat GCJ02 坐标纬度
41	     * @return BD09 坐标：[经度，纬度]
42	     */
43	    public static double[] gcj02ToBd09(double lng, double lat) {
44	        double z = Math.sqrt(lng * lng + lat * lat) + 0.00002 * Math.sin(lat * X_PI);
45	        double theta = Math.atan2(lat, lng) + 0.000003 * Math.cos(lng * X_PI);
46	        double bd_lng = z * Math.cos(theta) + 0.0065;
47	        double bd_lat = z * Math.sin(theta) + 0.006;
48	        return new double[]{bd_lng, bd_lat};
49	    }
50	
51	    /**
52	     * GCJ02 坐标转 WGS84 坐标
53	     *
54	     * @param lng GCJ02 坐标经度
55	     * @param lat GCJ02 坐标纬度
56	     * @return WGS84 坐标：[经度，纬度]
57	     */
58	    public static double[] gcj02ToWGS84(double lng, double lat) {
59	        if (outOfChina(lng, lat)) {
60	            return new double[]{lng, lat};
61	        }
62	        double dlat = transformLat(lng - 105.0, lat - 35.0);
63	        double dlng = transformLng(lng - 105.0, lat - 35.0);
64	        double radlat = lat / 180.0 * PI;
65	        double magic = Math.sin(radlat);
66	        magic = 1 - EE * magic * magic;
67	        double sqrtmagic = Math.sqrt(magic);
68	        dlat = (dlat * 180.0) / ((A * (1 - EE)) / (magic * sqrtmagic) * PI);
69	        dlng = (dlng * 180.0) / (A / sqrtmagic * Math.cos(radlat) * PI);
70	        double mglat = lat + dlat;
71	        double mglng = lng + dlng;
72	        return new double[]{lng * 2 - mglng, lat * 2 - mglat};
73	    }
74	
75	    /**
76	     * WGS84 坐标转 GCJ02 坐标
77	     *
78	     * @param lng WGS84 坐标经度
79	     * @param lat WGS84 坐标纬度
80	     * @return GCJ02 坐标：[经度，纬度]
81	     */
82	    public static double[] wgs84ToGcj02(double lng, double lat) {
83	        if (outOfChina(lng, lat)) {
84	            return new double[]{lng, lat};
85	        }
86	        double dlat = transformLat(lng - 105.0, lat - 35.0);
87	        double dlng = transformLng(lng - 105.0, lat - 35.0);
88	        double radlat = lat / 180.0 * PI;
89	        double magic = Math.sin(radlat);
90	        magic = 1 - EE * magic * magic;
91	        double sqrtmagic = Math.sqrt(magic);
92	        dlat = (dlat * 180.0) / ((A * (1 - EE)) / (magic * sqrtmagic) * PI);
93	        dlng = (dlng * 180.0) / (A / sqrtmagic * Math.cos(radlat) * PI);
94	        double mglat = lat + dlat;
95	        double mglng = lng + dlng;
96	        return new double[]{mglng, mglat};
97	    }
98	
99	    /**
100	     * BD09 坐标转 WGS84 坐标
101	     *
102	     * @param lng BD09 坐标经度
103	     * @param lat BD09 坐标纬度
104	     * @return WGS84 坐标：[经度，纬度]
105	     */
106	    public static double[] bd09ToWGS84(double lng, double lat) {
107	        double[] gcj = bd09ToGcj02(lng, lat);
108	        return gcj02ToWGS84(gcj[0], gcj[1]);
109	    }
110	
111	
112	    /**
113	     * WGS84 坐标转 BD09 坐标
114	     *
115	     * @param lng WGS84 坐标经度
116	     * @param lat WGS84 坐标纬度
117	     * @return BD09 坐标：[经度，纬度]
118	     */
119	    public static double[] wgs84ToBd09(double lng, double lat) {
120	        double[] gcj = wgs84ToGcj02(lng, lat);
121	        return gcj02ToBd09(gcj[0], gcj[1]);
122	    }
123	
124	    /**
125	     * Mercator 坐标转 WGS84 坐标
126	     *
127	     * @param lng Mercator 坐标经度
128	     * @param lat Mercator 坐标纬度
129	     * @return WGS84 坐标：[经度，纬度]
130	     */
131	    public static double[] mercatorToWGS84(double lng, double lat) {
132	        double x = lng / 20037508.34d * 180.;
133	        double y = lat / 20037508.34d * 180.;
134	        y = 180 / PI * (2 * Math.atan(Math.exp(y * PI / 180.0)) - PI / 2);
135	        return new double[]{x, y};
136	    }
137	
138	    /**
139	     * WGS84 坐标转 Mercator 坐标
140	     *
141	     * @param lng WGS84 坐标经度
142	     * @param lat WGS84 坐标纬度
143	     * @return Mercator 坐标：[经度，纬度]
144	     */
145	    public static double[] wgs84ToMercator(double lng, double lat) {
146	        double x = lng * 20037508.34D / 180.0;
147	        double y = Math.log(Math.tan((90.0 + lat) * PI / 360.0)) / (PI / 180.);
148	        y = y * 20037508.34D / 180.0;
149	        return new double[]{x, y};
150	    }
151	
152	    private static double transformLat(double lng, double lat) {
153	        double ret = -100.0 + 2.0 * lng + 3.0 * lat + 0.2 * lat * lat + 0.1 * lng * lat + 0.2 * Math.sqrt(Math.abs(lng));
154	        ret += (20.0 * Math.sin(6.0 * lng * PI) + 20.0 * Math.sin(2.0 * lng * PI)) * 2.0 / 3.0;
155	        ret += (20.0 * Math.sin(lat * PI) + 40.0 * Math.sin(lat / 3.0 * PI)) * 2.0 / 3.0;
156	        ret += (160.0 * Math.sin(lat / 12.0 * PI) + 320 * Math.sin(lat * PI / 30.0)) * 2.0 / 3.0;
157	        return ret;
158	    }
159	
160	    private static double transformLng(double lng, double lat) {
161	        double ret = 300.0 + lng + 2.0 * lat + 0.1 * lng * lng + 0.1 * lng * lat + 0.1 * Math.sqrt(Math.abs(lng));
162	        ret += (20.0 * Math.sin(6.0 * lng * PI) + 20.0 * Math.sin(2.0 * lng * PI)) * 2.0 / 3.0;
163	        ret += (20.0 * Math.sin(lng * PI) + 40.0 * Math.sin(lng / 3.0 * PI)) * 2.0 / 3.0;
164	        ret += (150.0 * Math.sin(lng / 12.0 * PI) + 300.0 * Math.sin(lng / 30.0 * PI)) * 2.0 / 3.0;
165	        return ret;
166	    }
167	
168	    private static boolean outOfChina(double lng, double lat) {
169	        return lng < 72.004 || lng > 137.8347 || lat < 0.8293 || lat > 55.8271;
170	    }
171	}
