21	public class FileHelper {
22	
23	    public static final int IMAGE   = 0;
24	    public static final int SP      = 1;
25	    public static final int UTF8    = 2;
26	    public static final int UNKNOWN = -1;
27	
28	    @IntDef({IMAGE, SP, UTF8, UNKNOWN})
29	    @Retention(RetentionPolicy.SOURCE)
30	    public @interface FileType {
31	    }
32	
33	    @FileType
34	    public static int getFileType(String path) {
35	        return getFileType(FileUtils.getFileByPath(path));
36	    }
37	
38	    @FileType
39	    public static int getFileType(File file) {
40	        if (!FileUtils.isFileExists(file)) return UNKNOWN;
41	        if (ImageUtils.isImage(file)) {
42	            return IMAGE;
43	        }
44	        if (FileUtils.getFileExtension(file).equals("xml")) {
45	            File parentFile = file.getParentFile();
46	            if (parentFile != null) {
47	                if (StringUtils.equals(parentFile.getName(), "shared_prefs")) {
48	                    return SP;
49	                }
50	            }
51	        }
52	        if (FileUtils.isUtf8(file)) {
53	            return UTF8;
54	        }
55	        return UNKNOWN;
56	    }
57	}
