171	        String command = "LD_LIBRARY_PATH=/vendor/lib*:/system/lib* pm uninstall "
172	                + (isKeepData ? "-k " : "")
173	                + packageName;
174	        ShellUtils.CommandResult commandResult = ShellUtils.execCmd(command, isRooted);
175	        if (commandResult.successMsg != null
176	                && commandResult.successMsg.toLowerCase().contains("success")) {
