193	    private static boolean isSpace(final String s) {
194	        if (s == null) return true;
195	        for (int i = 0, len = s.length(); i < len; ++i) {
196	            if (!Character.isWhitespace(s.charAt(i))) {
197	                return false;
198	            }
199	        }
200	        return true;
201	    }
