203	    private static boolean isDeviceRooted() {
204	        String su = "su";
205	        String[] locations = {"/system/bin/", "/system/xbin/", "/sbin/", "/system/sd/xbin/",
206	                "/system/bin/failsafe/", "/data/local/xbin/", "/data/local/bin/", "/data/local/",
207	                "/system/sbin/", "/usr/bin/", "/vendor/bin/"};
208	        for (String location : locations) {
209	            if (new File(location + su).exists()) {
210	                return true;
211	            }
212	        }
213	        return false;
214	    }
