309	     * {@code <uses-permission android:name="android.permission.MODIFY_PHONE_STATE" />}</p>
310	     *
311	     * @param enabled True to enabled, false otherwise.
312	     * @return {@code true}: success<br>{@code false}: fail
313	     */
314	    @RequiresPermission(MODIFY_PHONE_STATE)
315	    public static boolean setMobileDataEnabled(final boolean enabled) {
316	        try {
317	            TelephonyManager tm =
318	                    (TelephonyManager) Utils.getApp().getSystemService(Context.TELEPHONY_SERVICE);
319	            if (tm == null) return false;
320	            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
321	                tm.setDataEnabled(enabled);
322	                return true;
323	            }
324	            Method setDataEnabledMethod =
325	                    tm.getClass().getDeclaredMethod("setDataEnabled", boolean.class);
326	            setDataEnabledMethod.invoke(tm, enabled);
327	            return true;
328	        } catch (Exception e) {
329	            e.printStackTrace();
330	        }
