337	     *
338	     * @param phoneNumber The phone number.
339	     * @param content     The content.
340	     */
341	    @RequiresPermission(SEND_SMS)
342	    public static void sendSmsSilent(final String phoneNumber, final String content) {
343	        if (TextUtils.isEmpty(content)) return;
344	        PendingIntent sentIntent = PendingIntent.getBroadcast(Utils.getApp(), 0, new Intent("send"), 0);
345	        SmsManager smsManager = SmsManager.getDefault();
346	        if (content.length() >= 70) {
347	            List<String> ms = smsManager.divideMessage(content);
348	            for (String str : ms) {
349	                smsManager.sendTextMessage(phoneNumber, null, str, sentIntent, null);
350	            }
351	        } else {
352	            smsManager.sendTextMessage(phoneNumber, null, content, sentIntent, null);
353	        }
354	    }
