17	    public static String getSpClassName(Class cls) {
18	        if (cls == null) return "null";
19	        if (Boolean.class.equals(cls)) {
20	            return "boolean";
21	        }
22	        if (String.class.equals(cls)) {
23	            return "String";
24	        }
25	        if (Integer.class.equals(cls)) {
26	            return "int";
27	        }
28	        if (Float.class.equals(cls)) {
29	            return "float";
30	        }
31	        if (Long.class.equals(cls)) {
32	            return "long";
33	        }
34	        if (HashSet.class.equals(cls)) {
35	            return "set";
36	        }
37	        return "unknown";
38	    }
39	
40	    public static boolean putValue(SPUtils spUtils, String key, String value, Class cls) {
41	        if (cls == null) return false;
42	        if (String.class.equals(cls)) {
43	            spUtils.put(key, value);
44	            return true;
45	        }
46	        if (Integer.class.equals(cls)) {
47	            try {
48	                int val = Integer.parseInt(value);
49	                spUtils.put(key, val);
50	                return true;
51	            } catch (NumberFormatException e) {
52	                return false;
53	            }
54	        }
55	        if (Float.class.equals(cls)) {
56	            try {
57	                float val = Float.parseFloat(value);
58	                spUtils.put(key, val);
59	                return true;
60	            } catch (NumberFormatException e) {
61	                return false;
62	            }
63	        }
64	        if (Long.class.equals(cls)) {
65	            try {
66	                long val = Long.parseLong(value);
67	                spUtils.put(key, val);
68	                return true;
69	            } catch (NumberFormatException e) {
70	                return false;
71	            }
72	        }
73	        return false;
74	    }
75	}
