185	    public static List<FileItem> getFileItems(final FileItem parent) {
186	        if (parent == null) return getFileItems();
187	        List<File> files = FileUtils.listFilesInDir(parent.getFile(), new Comparator<File>() {
188	            @Override
189	            public int compare(File o1, File o2) {
190	                if (o1.isDirectory() && o2.isFile()) {
191	                    return -1;
192	                } else if (o1.isFile() && o2.isDirectory()) {
193	                    return 1;
194	                } else {
195	                    return o1.getName().toLowerCase().compareTo(o2.getName().toLowerCase());
196	                }
197	            }
198	        });
199	        return (List<FileItem>) CollectionUtils.collect(files, new CollectionUtils.Transformer<File, FileItem>() {
200	            @Override
201	            public FileItem transform(File input) {
202	                return new FileItem(parent, input);
203	            }
204	        });
205	    }
206	
207	    private static List<FileItem> getFileItems() {
208	        List<FileItem> fileItems = new ArrayList<>();
209	        String internalAppDataPath = PathUtils.getInternalAppDataPath();
210	        if (!StringUtils.isEmpty(internalAppDataPath)) {
211	            File internalDataFile = new File(internalAppDataPath);
212	            if (internalDataFile.exists()) {
213	                fileItems.add(new FileItem(internalDataFile, "internal"));
214	            }
215	        }
216	        String externalAppDataPath = PathUtils.getExternalAppDataPath();
217	        if (!StringUtils.isEmpty(externalAppDataPath)) {
218	            File externalDataFile = new File(externalAppDataPath);
219	            if (externalDataFile.exists()) {
220	                fileItems.add(new FileItem(externalDataFile, "external"));
221	            }
222	        }
223	        List<String> mountedSDCardPath = SDCardUtils.getMountedSDCardPath();
224	        if (!mountedSDCardPath.isEmpty()) {
225	            for (int i = 0; i < mountedSDCardPath.size(); i++) {
226	                String path = mountedSDCardPath.get(i);
227	                File sdPath = new File(path);
228	                if (sdPath.exists()) {
229	                    fileItems.add(new FileItem(sdPath, "sdcard" + i + "_" + sdPath.getName(), true));
230	                }
231	            }
232	        }
233	        return fileItems;
234	    }
235	
236	    public static List<FileItem> filterItems(List<FileItem> items, final String key) {
237	        return (List<FileItem>) CollectionUtils.select(items, new CollectionUtils.Predicate<FileItem>() {
238	            @Override
239	            public boolean evaluate(FileItem item) {
240	                return item.mName.toLowerCase().contains(key.toLowerCase());
241	            }
242	        });
243	    }
244	
245	    public static boolean isEmptyItems(List<FileItem> items) {
246	        return EMPTY == items;
247	    }
