267	    /**
268	     * 是否更好的位置
269	     *
270	     * @param newLocation         The new Location that you want to evaluate
271	     * @param currentBestLocation The current Location fix, to which you want to compare the new one
272	     * @return {@code true}: 是<br>{@code false}: 否
273	     */
274	    public static boolean isBetterLocation(Location newLocation, Location currentBestLocation) {
275	        if (currentBestLocation == null) {
276	            // A new location is always better than no location
277	            return true;
278	        }
279	
280	        // Check whether the new location fix is newer or older
281	        long timeDelta = newLocation.getTime() - currentBestLocation.getTime();
282	        boolean isSignificantlyNewer = timeDelta > TWO_MINUTES;
283	        boolean isSignificantlyOlder = timeDelta < -TWO_MINUTES;
284	        boolean isNewer = timeDelta > 0;
285	
286	        // If it's been more than two minutes since the current location, use the new location
287	        // because the user has likely moved
288	        if (isSignificantlyNewer) {
289	            return true;
290	            // If the new location is more than two minutes older, it must be worse
291	        } else if (isSignificantlyOlder) {
292	            return false;
293	        }
294	
295	        // Check whether the new location fix is more or less accurate
296	        int accuracyDelta = (int) (newLocation.getAccuracy() - currentBestLocation.getAccuracy());
297	        boolean isLessAccurate = accuracyDelta > 0;
298	        boolean isMoreAccurate = accuracyDelta < 0;
299	        boolean isSignificantlyLessAccurate = accuracyDelta > 200;
300	
301	        // Check if the old and new location are from the same provider
302	        boolean isFromSameProvider = isSameProvider(newLocation.getProvider(), currentBestLocation.getProvider());
303	
304	        // Determine location quality using a combination of timeliness and accuracy
305	        if (isMoreAccurate) {
306	            return true;
307	        } else if (isNewer && !isLessAccurate) {
308	            return true;
309	        } else if (isNewer && !isSignificantlyLessAccurate && isFromSameProvider) {
310	            return true;
311	        }
312	        return false;
313	    }
