350	        @Override
351	        public void onStatusChanged(String provider, int status, Bundle extras) {
352	            if (mListener != null) {
353	                mListener.onStatusChanged(provider, status, extras);
354	            }
355	            switch (status) {
356	                case LocationProvider.AVAILABLE:
357	                    Log.d("LocationUtils", "当前GPS状态为可见状态");
358	                    break;
359	                case LocationProvider.OUT_OF_SERVICE:
360	                    Log.d("LocationUtils", "当前GPS状态为服务区外状态");
361	                    break;
362	                case LocationProvider.TEMPORARILY_UNAVAILABLE:
363	                    Log.d("LocationUtils", "当前GPS状态为暂停服务状态");
364	                    break;
365	            }
366	        }
