23	 */
24	public final class Request {
25	
26	    URL                 mURL;
27	    Map<String, String> mHeader;
28	    Body                mBody;
29	
30	    public static Request withUrl(@NonNull final String url) {
31	        return new Request(url);
32	    }
33	
34	    private Request(final String url) {
35	        try {
36	            mURL = new URL(url);
37	        } catch (MalformedURLException e) {
38	            e.printStackTrace();
39	        }
40	    }
41	
42	    public Request addHeader(@NonNull final String name, @NonNull final String value) {
43	        if (mHeader == null) {
44	            mHeader = new HashMap<>();
45	        }
46	        mHeader.put(name, value);
47	        return this;
48	    }
49	
50	    public Request addHeader(@NonNull final Map<String, String> header) {
51	        if (this.mHeader == null) {
52	            this.mHeader = new HashMap<>();
53	        }
54	        this.mHeader.putAll(header);
55	        return this;
56	    }
57	
58	    public Request post(@NonNull final Body body) {
59	        this.mBody = body;
60	        return this;
61	    }
62	
63	    public static class Body {
64	        String              mediaType;
65	        BufferedInputStream bis;
66	        long                length;
67	
68	        private Body(final String mediaType, final byte[] body) {
69	            this.mediaType = mediaType;
70	            bis = new BufferedInputStream(new ByteArrayInputStream(body));
71	            length = body.length;
72	        }
73	
74	        private Body(final String mediaType, final InputStream body) {
75	            this.mediaType = mediaType;
76	            if (body instanceof BufferedInputStream) {
77	                bis = (BufferedInputStream) body;
78	            } else {
79	                bis = new BufferedInputStream(body);
80	            }
81	            length = -1;
82	        }
83	
84	        private static String getCharsetFromMediaType(String mediaType) {
85	            mediaType = mediaType.toLowerCase().replace(" ", "");
86	            int index = mediaType.indexOf("charset=");
87	            if (index == -1) return "utf-8";
88	            int st = index + 8;
89	            int end = mediaType.length();
90	            if (st >= end) {
91	                throw new IllegalArgumentException("MediaType is not correct: \"" + mediaType + "\"");
92	            }
93	            for (int i = st; i < end; i++) {
94	                char c = mediaType.charAt(i);
95	                if (c >= 'A' && c <= 'Z') continue;
96	                if (c >= 'a' && c <= 'z') continue;
97	                if (c >= '0' && c <= '9') continue;
98	                if (c == '-' && i != 0) continue;
99	                if (c == '+' && i != 0) continue;
100	                if (c == ':' && i != 0) continue;
101	                if (c == '_' && i != 0) continue;
102	                if (c == '.' && i != 0) continue;
103	                end = i;
104	                break;
105	            }
106	            String charset = mediaType.substring(st, end);
107	            return checkCharset(charset);
108	        }
109	
110	        public static Body create(@NonNull String mediaType, @NonNull byte[] content) {
111	            return new Body(mediaType, content);
112	        }
113	
114	        public static Body form(@NonNull final Map<String, String> form) {
115	            return form(form, "utf-8");
116	        }
117	
118	        public static Body form(@NonNull final Map<String, String> form, String charset) {
119	            String mediaType = "application/x-www-form-urlencoded;charset=" + checkCharset(charset);
120	            final StringBuilder sb = new StringBuilder();
121	            for (String key : form.keySet()) {
122	                if (sb.length() > 0) sb.append("&");
123	                sb.append(key).append("=").append(form.get(key));
124	            }
125	            try {
126	                return new Body(mediaType, sb.toString().getBytes(charset));
127	            } catch (UnsupportedEncodingException e) {
128	                e.printStackTrace();
129	                return null;
130	            }
131	        }
132	
133	        public static Body json(@NonNull final String json) {
134	            return json(json, "utf-8");
135	        }
136	
137	        public static Body json(@NonNull final String json, String charset) {
138	            String mediaType = "application/json;charset=" + checkCharset(charset);
139	            try {
140	                return new Body(mediaType, json.getBytes(charset));
141	            } catch (UnsupportedEncodingException e) {
142	                e.printStackTrace();
143	                return null;
144	            }
145	        }
146	
147	//        public static RequestBody file(String mediaType, final File file) {
148	//
149	//            return new RequestBody(mediaType, );
150	//        }
151	
152	    }
153	
154	    private static String checkCharset(final String charset) {
155	        if (Charset.isSupported(charset)) return charset;
156	        throw new IllegalCharsetNameException(charset);
157	    }
158	}
